#!/bin/sh
# Differential test of the SPARK Unishox2 port against the C reference.
#  1. builds reference/unishox2.c with clang into tests/build/libunishox2_ref.a;
#  2. builds the library with all run-time checks and contracts enabled, and the test;
#  3. runs the fixed corpus (tests/corpus.txt, regenerated by gen_corpus.py),
#     N random round trips and N decoder fuzz cases (fixed seed).
# Usage: tests/run.sh [round trips (default 100000)] [decoder fuzz cases (default 100000)]
set -eu
HERE=$(cd "$(dirname "$0")" && pwd)
ROOT=$(dirname "$HERE")
. "$ROOT/env.sh"
B="$HERE/build"
mkdir -p "$B"

python3 -I "$HERE/gen_corpus.py" > "$B/corpus.txt"
if ! cmp -s "$B/corpus.txt" "$HERE/corpus.txt"; then
  echo "tests/corpus.txt is out of date with gen_corpus.py" >&2; exit 1
fi

# The reference: -fwrapv because malformed input can overflow its int arithmetic
clang -O2 -fwrapv -w -DUNISHOX_API_WITH_OUTPUT_LEN=1 -I"$ROOT/reference" \
  -c "$ROOT/reference/unishox2.c" -o "$B/unishox2.o"
clang -O2 -Wall -DUNISHOX_API_WITH_OUTPUT_LEN=1 -I"$ROOT/reference" \
  -c "$HERE/c/ref_wrap.c" -o "$B/ref_wrap.o"
rm -f "$B/libunishox2_ref.a"
ar rcs "$B/libunishox2_ref.a" "$B/unishox2.o" "$B/ref_wrap.o"

gprbuild -q -p -P "$HERE/tests.gpr" -XUNISHOX_BUILD_MODE=checks > "$B/build.log" 2>&1 \
  || { grep -v 'deployment version' "$B/build.log"; exit 1; }
"$B/test_unishox" "$HERE/corpus.txt" "${1:-100000}" "${2:-100000}"
